--
-- Name: actualizar_puntos_docente(); Type: FUNCTION; Schema: public; Owner: gestion_uq
--

CREATE FUNCTION public.actualizar_puntos_docente() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  diff NUMERIC := 0;
  target_cedula TEXT;
BEGIN
  -- CASO 1: Nueva solicitud insertada ya como aprobada
  IF TG_OP = 'INSERT' THEN
    IF NEW.estado = 'aprobado' THEN
      diff := COALESCE(NEW.pts_asig, 0);
      target_cedula := NEW.cedula;
    END IF;
    
  -- CASO 2: Solicitud actualizada
  ELSIF TG_OP = 'UPDATE' THEN
    -- Pasa de otro estado a 'aprobado'
    IF NEW.estado = 'aprobado' AND (OLD.estado IS NULL OR OLD.estado <> 'aprobado') THEN
      diff := COALESCE(NEW.pts_asig, 0);
      
    -- Pasa de 'aprobado' a otro estado (se reversa)
    ELSIF (NEW.estado IS NULL OR NEW.estado <> 'aprobado') AND OLD.estado = 'aprobado' THEN
      diff := -COALESCE(OLD.pts_asig, 0);
      
    -- Estaba 'aprobado', sigue 'aprobado', pero cambian los puntos asignados
    ELSIF NEW.estado = 'aprobado' AND OLD.estado = 'aprobado' AND COALESCE(NEW.pts_asig, 0) <> COALESCE(OLD.pts_asig, 0) THEN
      diff := COALESCE(NEW.pts_asig, 0) - COALESCE(OLD.pts_asig, 0);
    END IF;
    
    target_cedula := NEW.cedula;
    
  -- CASO 3: Solicitud eliminada
  ELSIF TG_OP = 'DELETE' THEN
    IF OLD.estado = 'aprobado' THEN
      diff := -COALESCE(OLD.pts_asig, 0);
      target_cedula := OLD.cedula;
    END IF;
  END IF;

  -- Si hay diferencia real, actualizar la tabla del docente
  IF diff <> 0 AND target_cedula IS NOT NULL THEN
    UPDATE docentes
    SET pts_acumulados = COALESCE(pts_acumulados, 0) + diff
    WHERE cedula = target_cedula;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


